param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}

function Name([type]$t){if($t.IsByRef){return (Name $t.GetElementType())+'&'};if($t.IsPointer){return (Name $t.GetElementType())+'*'};if($t.IsArray){return (Name $t.GetElementType())+'[]'};if($t.IsGenericType){return $t.GetGenericTypeDefinition().FullName+'<'+((@($t.GetGenericArguments()|ForEach-Object{Name $_})) -join ',')+'>'};return $t.FullName}
function Failure($r){$e=$r.Exception;while($e.InnerException){$e=$e.InnerException};$f=[ordered]@{type=$e.GetType().FullName;message=$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})};if($e -is [Text.EncoderFallbackException]){$f.index=$e.Index;$f.charUnknown=[int]$e.CharUnknown;$f.high=[int]$e.CharUnknownHigh;$f.low=[int]$e.CharUnknownLow;$f.isPair=$e.IsUnknownSurrogate()};if($e -is [Text.DecoderFallbackException]){$f.index=$e.Index;$f.bytes=[int[]]@($e.BytesUnknown|ForEach-Object{[int]$_})};return $f}
$type=[Text.UnicodeEncoding];$declared=[Reflection.BindingFlags]'Public,Instance,Static,DeclaredOnly';$methods=@($type.GetMethods($declared)|ForEach-Object{[ordered]@{name=$_.Name;returnType=(Name $_.ReturnType);parameters=@($_.GetParameters()|ForEach-Object{[ordered]@{name=$_.Name;type=(Name $_.ParameterType)}});isVirtual=$_.IsVirtual;isFinal=$_.IsFinal}}|Sort-Object {($_|ConvertTo-Json -Depth 10 -Compress)})
$constructors=@($type.GetConstructors()|ForEach-Object{,@($_.GetParameters()|ForEach-Object{[ordered]@{name=$_.Name;type=(Name $_.ParameterType)}})})
$encodings=[Collections.Generic.List[Text.UnicodeEncoding]]::new();$specs=[Collections.Generic.List[object]]::new()
foreach($kind in 0..8){$big=$false;$bom=$true;$strict=$false;if($kind -eq 0){$owner=[Text.UnicodeEncoding]::new()}else{$bits=$kind-1;$big=($bits -band 4) -ne 0;$bom=($bits -band 2) -ne 0;$strict=($bits -band 1) -ne 0;$owner=[Text.UnicodeEncoding]::new($big,$bom,$strict)};foreach($custom in @($false,$true)){if($custom){$owner=[Text.UnicodeEncoding]$owner.Clone();$owner.EncoderFallback=[Text.EncoderReplacementFallback]::new('AB');$owner.DecoderFallback=[Text.DecoderReplacementFallback]::new('CD')};$encodings.Add($owner);$preamble=$owner.GetPreamble();$specs.Add([ordered]@{constructor=$kind;bigEndian=$big;bom=$bom;strict=$strict;custom=$custom;codePage=$owner.CodePage;readOnly=$owner.IsReadOnly;webName=$owner.WebName;encodingName=$owner.EncodingName;singleByte=$owner.IsSingleByte;encoderFallback=$owner.EncoderFallback.GetType().FullName;decoderFallback=$owner.DecoderFallback.GetType().FullName;encoderMax=$owner.EncoderFallback.MaxCharCount;decoderMax=$owner.DecoderFallback.MaxCharCount;encoderHash=$owner.EncoderFallback.GetHashCode();decoderHash=$owner.DecoderFallback.GetHashCode();hash=$owner.GetHashCode();preamble=[int[]]@($preamble|ForEach-Object{[int]$_});preambleIdentity=[object]::ReferenceEquals($preamble,$owner.GetPreamble())})}}
$chars=@(@(),@(0),@(65),@(127,128,255,256,2047,2048),@(55295,57344,65535),@(55296,56320),@(56319,57343),@(55357,56832),@(55296),@(56320),@(55296,65),@(65,56320),@(55296,55296),@(56320,56320),@(55296,56320,55296),@(65,55296,56320,66))
$bytes=@(@(),@(0),@(65),@(0,65),@(65,0),@(255,254),@(254,255),@(0,216),@(216,0),@(0,220),@(220,0),@(0,216,0,220),@(216,0,220,0),@(0,216,65),@(0,216,65,0),@(65,0,216,0),@(255,255,0),@(0,0,255,255))
$rows=[Collections.Generic.List[object]]::new();foreach($i in 0..($encodings.Count-1)){$owner=$encodings[$i];foreach($direction in @('encode','decode')){$unitsInputs=if($direction -eq 'encode'){,$chars}else{,$bytes};foreach($unitsInput in $unitsInputs){foreach($countOnly in @($true,$false)){$result=$null;$failure=$null;try{if($direction -eq 'encode'){$source=[char[]]$unitsInput;$result=if($countOnly){$owner.GetByteCount($source)}else{,[int[]]@($owner.GetBytes($source)|ForEach-Object{[int]$_})}}else{$source=[byte[]]$unitsInput;$result=if($countOnly){$owner.GetCharCount($source)}else{,[int[]]@($owner.GetChars($source)|ForEach-Object{[int]$_})}}}catch{$failure=Failure $_};$rows.Add([ordered]@{state=$i;direction=$direction;input=[int[]]$unitsInput;countOnly=$countOnly;result=$result;failure=$failure})}}}}
$maximums=[Collections.Generic.List[object]]::new();foreach($i in 0..($encodings.Count-1)){foreach($count in @(-1,0,1,2,3,10,1073741822,1073741823,1073741824,2147483647)){foreach($encode in @($false,$true)){$result=$null;$failure=$null;try{$result=if($encode){$encodings[$i].GetMaxByteCount($count)}else{$encodings[$i].GetMaxCharCount($count)}}catch{$failure=Failure $_};$maximums.Add([ordered]@{state=$i;count=$count;encode=$encode;result=$result;failure=$failure})}}}
$equalities=[Collections.Generic.List[object]]::new();foreach($left in 0..($encodings.Count-1)){foreach($right in 0..($encodings.Count-1)){$equalities.Add([ordered]@{left=$left;right=$right;equal=$encodings[$left].Equals($encodings[$right])})}}
$record=[ordered]@{schemaVersion=1;culture=[Globalization.CultureInfo]::CurrentCulture.Name;uiCulture=[Globalization.CultureInfo]::CurrentUICulture.Name;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();nativeType=$type.FullName;charSize=[Text.UnicodeEncoding]::CharSize;constructors=$constructors;methods=$methods;specs=$specs.ToArray();rows=$rows.ToArray();maximums=$maximums.ToArray();equalities=$equalities.ToArray();qualification='UTF16_NATIVE_REFERENCE_AND_IMPLEMENTATION_PLAN_INPUT_ONLY; NO_JAVA_UNICODEENCODING_IMPLEMENTATION_STATEFUL_SOURCE_ABI_E01_OR_TASK_ACCEPTANCE_CREDIT'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 18 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS UTF16 native plan capture: $($specs.Count) states, $($methods.Count) declared methods, $($rows.Count) conversion rows, $($maximums.Count) maximum-count rows, $($equalities.Count) comparisons"
